import{_ as s,a0 as a,w as p,s as l,ao as d,I as i,x as e,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何使用安卓設備控制你的Linux PC | LCTT x X-CMD","titleTemplate":false,"description":"如何使用安卓設備控制你的Linux PC | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用安卓設備控制你的Linux PC | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用安卓設備控制你的Linux PC | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to Control Your Linux PC with an Android Device","title":"如何使用安卓設備控制你的Linux PC","tag":"201311","desc":""},"relativePath":"201311/How to Control Your Linux PC with an Android Device.md","filePath":"[post].md"}'),u={name:"201311/How to Control Your Linux PC with an Android Device.md"};function h(m,t,x,C,S,c){const o=a("Link");return p(),l("div",null,[t[11]||(t[11]=d(`<h1 id="如何使用安卓設備控制你的linux-pc" tabindex="-1">如何使用安卓設備控制你的Linux PC <a class="header-anchor" href="#如何使用安卓設備控制你的linux-pc" aria-label="Permalink to “如何使用安卓設備控制你的Linux PC”">​</a></h1><p><strong>下面的教程會指導所有的Linux用户如何在系統上安裝SSH，以便通過安卓智能手機遠程訪問他們的電腦。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Control-Your-Linux-PC-with-an-Android-Device-396004-2.jpg" alt=""> 如今我們所有人都擁有一台平板或觸屏手機，我們經常使用它們在深夜裏看電影或電視節目，聽歌或者讀一本好書。你可以把本文稱作是“懶人教程”，它是專門為那些在大晚上因為太過疲憊而懶得去開啓他們電腦上的某些應用程序，移動、刪除，複製或重命名某些文件，甚至懶得去關掉PC的人準備的。</p><p>的確，已經有各種各樣的遠程桌面解決方案，但是許多方案費用很高，或者實現效果很糟糕，無法像預期一樣運行，迫使你最終還是得去電腦上做你原本想做的事情。</p><p>在這個教程裏面，我們將使用一種簡單、安全、高效的協議，它被稱為SSH (Secure Shell)，很容易從默認的軟件倉庫中安裝（在Arch linx中是openssh，在Ubuntu中是openssh-server）。</p><h3 id="配置ssh服務器" tabindex="-1">配置SSH服務器 <a class="header-anchor" href="#配置ssh服務器" aria-label="Permalink to “配置SSH服務器”">​</a></h3><p>在安裝完成後，你需要為SSH服務器進行基本配置。為此，你需要使用文本編輯器編輯/etc/ssh/sshd_config這個文件。</p><p>1.在文件尾部添加下面一行（下面的yourusername使用你的Linux機器上存在的用户名代替）</p><p>AllowUsers yourusername</p><p>2.取消&quot;#PermitRootLogin&quot;這行註釋，把&quot;no&quot;替換成&quot;yes&quot;（譯註：下面的選項修改和是否允許ssh登錄無關，只是允許root直接登錄，一般而言，並不建議如下這樣的遠程root直接登錄。）：</p><pre><code>PermitRootLogin no
</code></pre><p>3.為了安全起見，你需要修改SSH 連接默認的22端口到一個更大編號的端口，譬如在我們的例子中是55441 （但不要使用55441，這是我舉個列子，可以找另一個四位或者五位數字）。因此，取消註釋並編輯&quot;#Port 22&quot;如下（譯註：你可以選擇任何一個大於1024並小於65535的端口，只要他沒有被別的程序佔用，為什麼不試試你的幸運數字呢？）：</p><pre><code>   Port 55441
</code></pre><h3 id="開啓ssh服務器" tabindex="-1">開啓SSH服務器### <a class="header-anchor" href="#開啓ssh服務器" aria-label="Permalink to “開啓SSH服務器###”">​</a></h3><p>在Ubuntu上，SSH服務通過下面的命令啓動：</p><pre><code>sudo /etc/init.d/ssh start
</code></pre><p>當你每次修改上述配置文件時，都需要通過下面的命令重啓：</p><pre><code>sudo /etc/init.d/ssh restart
</code></pre><p>在Arch Linux上，你可以使用下面的命令啓動SSH服務：</p><pre><code>sudo systemctl start sshd
</code></pre><h3 id="配置安卓設備上的ssh客户端" tabindex="-1">配置安卓設備上的SSH客户端### <a class="header-anchor" href="#配置安卓設備上的ssh客户端" aria-label="Permalink to “配置安卓設備上的SSH客户端###”">​</a></h3><p>JuiceSSH似乎是安卓上最好的SSH客户端之一，而且是免費的。同時，如果你認為它的功能比較簡單，可以花費少量的錢來得到更多高級的特性，譬如亞馬遜 AWS/EC2 集成，團隊協作，以及更多其它的特性。</p><p>一旦軟件安裝完畢，開啓它，然後你會要求輸入一個加密的密碼以保證連接的安全。這個密碼由AES-256進行加密，因此除非你的設備被偷，否則沒有人能夠獲取它們。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/large/sshlinuxandroid-large_001.jpg" alt=""></p><p>現在，添加一個新連接，為你的電腦選擇名稱、IP地址，上面設定的端口號以及一個需要被創建的身份。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/large/sshlinuxandroid-large_002.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/large/sshlinuxandroid-large_003.jpg" alt=""></p><p>這就是我的Arch Linux機器，這是通過我的安卓平板上的JuiceSSH客户端訪問到的界面。如果在這個教程中你遇到問題，請在下面進行評論。</p><hr>`,29)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://news.softpedia.com/news/How-to-Control-Your-Linux-PC-with-an-Android-Device-396004.shtml"},{default:r(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/How-to-Control-Your-Linux-PC-with-an-Android-Device-396004.shtml",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(o,{href:"https://github.com/KayGuoWhu"},{default:r(()=>[...t[2]||(t[2]=[e("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const P=s(u,[["render",h]]);export{f as __pageData,P as default};
